insert into public.services (slug, number, title, subtitle, description, icon, category, technologies, deliverables, stat_label, stat_value, price_note, active, featured, sort_order, seo)
values
  ('website-development', '01', 'Website Development', 'High-performance React, Next.js & modern full-stack web applications.', 'We craft high-converting, modern web applications built on cutting-edge technologies like React, TypeScript, Next.js, Node.js, and Express. Whether you need an elite corporate web platform, a modern SaaS product, or a custom full-stack web portal, BRANIFY delivers pixel-perfect, secure, and lightning-fast solutions.', 'Globe', 'web', ARRAY['React','TypeScript','Next.js','Tailwind CSS','Node.js','Vite','PostgreSQL']::text[], ARRAY['Production Web Application Build','Full Source Code Repository','Admin Setup & Config','SEO Configuration','User Guide & Documentation Video']::text[], 'Starting price', 'Custom quote', '5–14 Days', true, true, 0, '{"title":"Website Development Services — BRANIFY","description":"Custom, blazing-fast, responsive web applications engineered for conversions, SEO, and international scalability."}'::jsonb),
  ('wordpress-development', '02', 'WordPress Development', 'Custom Elementor, WooCommerce & headless WordPress solutions.', 'Power your business with the world’s most versatile CMS. We build ultra-fast, tailored WordPress & WooCommerce stores that are easy for your team to manage, fully secured against vulnerabilities, and optimized for search engine rankings.', 'LayoutGrid', 'web', ARRAY['WordPress','PHP','WooCommerce','Elementor Pro','MySQL','Redis']::text[], ARRAY['Custom WordPress Build','WooCommerce Setup','Licensed Plugin Setup','Speed Optimization Audit Report','Admin Training Video']::text[], 'Starting price', 'Custom quote', '4–14 Days', true, true, 1, '{"title":"WordPress Development Services — BRANIFY","description":"Scalable, secure, and user-friendly WordPress websites with custom themes, Elementor Pro, WooCommerce, and speed optimization."}'::jsonb),
  ('landing-pages', '03', 'Landing Pages', 'High-converting lead generation & product launch pages.', 'Stop wasting ad spend on low-converting pages. BRANIFY crafts hyper-focused landing pages engineered around direct-response design principles, clear calls-to-action, mobile ergonomics, and instant loading speeds.', 'MousePointerClick', 'web', ARRAY['React','TypeScript','Tailwind CSS','Figma','Webhooks']::text[], ARRAY['High-Converting Landing Page Build','Persuasive Copywriting Outline','CRM & Webhook Integration','Pixel & Analytics Setup']::text[], 'Starting price', 'Custom quote', '3–7 Days', true, true, 2, '{"title":"Landing Pages Services — BRANIFY","description":"Psychology-driven, fast-loading landing pages designed to turn ad traffic into paying customers and qualified leads."}'::jsonb),
  ('ui-ux-design', '04', 'UI/UX Design', 'User-centric research, wireframes & high-fidelity Figma design systems.', 'Great software starts with exceptional user experience. We combine user research, wireframing, interactive prototyping, and reusable Figma design systems to turn complex workflows into delightful, effortless digital products.', 'Figma', 'design', ARRAY['Figma','FigJam','Design Tokens','Auto-Layout']::text[], ARRAY['Figma Source File','Interactive Prototype Link','Design System Library','Asset Exports (SVG/PNG)']::text[], 'Starting price', 'Custom quote', '4–14 Days', true, false, 3, '{"title":"UI/UX Design Services — BRANIFY","description":"Elevate your web or mobile product with intuitive user experience mapping, sleek visual design systems, and Figma prototypes."}'::jsonb),
  ('logo-design', '05', 'Logo Design', 'Memorable, modern, and vector-perfect brand logos.', 'Your logo is the visual cornerstone of your brand. Our designers craft unique, conceptual logo marks that communicate authority, trust, and distinction across digital screens, business cards, merchandise, and billboards.', 'Palette', 'branding', ARRAY['Adobe Illustrator','Figma','Vector Engine']::text[], ARRAY['Vector Master Files (AI, EPS, SVG, PDF)','High-Res PNG & JPG Packs','Favicon & App Icon Formats','Commercial Copyright Transfer']::text[], 'Starting price', 'Custom quote', '2–5 Days', true, false, 4, '{"title":"Logo Design Services — BRANIFY","description":"Distill your business essence into an iconic, timeless, and versatile vector logo that stands out across print and digital media."}'::jsonb),
  ('brand-identity', '06', 'Brand Identity', 'Complete visual branding: guidelines, typography & social kits.', 'In today’s crowded marketplace, visual consistency builds trust. BRANIFY constructs holistic brand identity systems including logo usage rules, color swatches, font pairings, business stationery, social media templates, and comprehensive brand books.', 'Sparkles', 'branding', ARRAY['Adobe Illustrator','InDesign','Figma']::text[], ARRAY['Brand Guidelines PDF','Logo Master Suite','Color & Typography Kit','Stationery Designs','Social Media Templates']::text[], 'Starting price', 'Custom quote', '4–14 Days', true, false, 5, '{"title":"Brand Identity Services — BRANIFY","description":"Transform your business into a cohesive, premium international brand with full style guidelines, stationery, and social kits."}'::jsonb),
  ('social-media-design', '07', 'Social Media Design', 'Engaging Instagram, LinkedIn, Facebook & YouTube ad creatives.', 'Stand out on feed algorithms with high-impact, custom social media designs tailored for Instagram, Facebook, LinkedIn, Twitter/X, and YouTube. We combine bold typography, custom graphics, and brand consistency to boost your engagement.', 'Share2', 'marketing', ARRAY['Canva','Photoshop','Figma','Illustrator']::text[], ARRAY['Post Graphics Pack','Carousel Slides','Ad Creatives','Editable Canva & Figma Templates']::text[], 'Starting price', 'Custom quote', '3–7 Days', true, false, 6, '{"title":"Social Media Design Services — BRANIFY","description":"Eye-catching social media posts, story templates, carousel graphics, reel covers, and ad creatives that stop the scroll."}'::jsonb),
  ('business-presentation', '08', 'Business Presentation', 'Investor pitch decks, sales presentations & company profiles.', 'Secure funding and close high-value deals with custom-designed presentations. We turn complex data, market statistics, and business strategy into visually compelling, easy-to-digest pitch decks in PowerPoint, Google Slides, or PDF.', 'Presentation', 'branding', ARRAY['PowerPoint','Google Slides','Figma','Illustrator']::text[], ARRAY['Editable PowerPoint (.pptx) File','Google Slides Link','Print-Ready PDF Deck','Custom Graphic Assets']::text[], 'Starting price', 'Custom quote', '3–7 Days', true, false, 7, '{"title":"Business Presentation Services — BRANIFY","description":"Captivate investors, board members, and clients with custom pitch decks, sales decks, and polished company profiles."}'::jsonb),
  ('seo', '09', 'SEO (Search Engine Optimization)', 'Technical, on-page, local SEO & keyword ranking strategies.', 'Drive sustainable, organic traffic to your website without relying solely on paid ads. Our SEO services cover deep technical fixes, keyword mapping, content structuring, schema markup, local SEO, and Google Search Console performance optimization.', 'Search', 'marketing', ARRAY['Google Search Console','Ahrefs','SEMrush','Schema.org','GA4']::text[], ARRAY['Technical Audit Report','Keyword Mapping Document','On-Page Meta Optimization','GSC & Analytics Setup']::text[], 'Starting price', 'Custom quote', '5–14 Days', true, false, 8, '{"title":"SEO (Search Engine Optimization) Services — BRANIFY","description":"Dominate Google search results with comprehensive technical audits, keyword strategy, schema markup, and speed optimization."}'::jsonb),
  ('ai-solutions', '10', 'AI Solutions', 'Custom AI chatbots, workflow automation & LLM integration.', 'Leverage state-of-the-art AI technology to automate customer support, generate smart business insights, and streamline daily operations. We build custom AI applications, Gemini/OpenAI API integrations, RAG knowledge bots, and automated workflows.', 'Bot', 'ai', ARRAY['Gemini API','TypeScript','Node.js','Vector DB','Express']::text[], ARRAY['Custom AI Widget / App','Server Proxy & API Integration','Prompt Engineering Architecture','Admin Control Panel']::text[], 'Starting price', 'Custom quote', '5–21 Days', true, false, 9, '{"title":"AI Solutions Services — BRANIFY","description":"Empower your business with custom AI chatbots, automated customer support, Gemini API workflows, and smart task automation."}'::jsonb),
  ('business-consultation', '11', 'Business Consultation', 'Strategic roadmap for digital transformation, branding & growth.', 'Unsure which technology stack to choose, how to rebrand, or how to implement AI in your operations? Sit down with BRANIFY strategy leads for an actionable consultation session that provides clear roadmaps, vendor audits, and growth blueprints.', 'TrendingUp', 'consulting', ARRAY['Google Meet','Strategy Blueprint','Audit System']::text[], ARRAY['1-on-1 Live Strategy Session','Custom Growth Blueprint PDF','Recorded Call Session','14-Day Email Q&A Access']::text[], 'Starting price', 'Custom quote', '1-on-1 Session', true, false, 10, '{"title":"Business Consultation Services — BRANIFY","description":"Get expert 1-on-1 strategic guidance on web technology, brand positioning, online scaling, and AI adoption for your business."}'::jsonb)
insert into public.tools (slug, name, category, description, icon, url, input_type, active, featured, popular, sort_order, seo)
values
  ('pdf-to-text', 'PDF Text Extractor', 'PDF Tools', 'Extract raw text content from PDF files directly in your browser without uploading to external servers.', 'FileText', '/tools/pdf-to-text', 'file', true, true, true, 0, '{"title":"Free PDF Text Extractor Tool — BRANIFY","description":"Extract text from any PDF document online instantly in your browser.","keywords":["pdf to text","extract pdf text","pdf reader","pdf converter"]}'::jsonb),
  ('pdf-word-counter', 'PDF Word Counter', 'PDF Tools', 'Count words, characters, pages, and estimated reading time from any PDF document.', 'Hash', '/tools/pdf-word-counter', 'file', true, false, false, 1, '{"title":"PDF Word Counter — BRANIFY Tools","description":"Instantly count total words, characters, and pages in a PDF file.","keywords":["pdf word count","count words in pdf","pdf reader"]}'::jsonb),
  ('pdf-metadata-viewer', 'PDF Metadata Viewer', 'PDF Tools', 'View hidden metadata, author information, creation dates, PDF producer, and version info.', 'Info', '/tools/pdf-metadata-viewer', 'file', true, false, false, 2, '{"title":"PDF Metadata & Properties Inspector","description":"Inspect PDF metadata including author, title, keywords, and creation dates.","keywords":["pdf metadata","inspect pdf","pdf properties"]}'::jsonb),
  ('pdf-page-counter', 'PDF Page Inspector & Splitter Helper', 'PDF Tools', 'Inspect page layouts, dimensions, aspect ratios, and total page count for PDF documents.', 'Layers', '/tools/pdf-page-counter', 'file', true, false, false, 3, '{"title":"PDF Page Structure & Inspector Tool","description":"Analyze PDF page dimensions, page count, and structural metadata.","keywords":["pdf pages","pdf inspector","pdf layout"]}'::jsonb),
  ('pdf-text-cleaner', 'PDF Copy Text Formatter', 'PDF Tools', 'Paste messy text copied from PDFs to strip out unwanted line breaks, hyphens, and weird spacing.', 'Sparkles', '/tools/pdf-text-cleaner', 'textarea', true, false, false, 4, '{"title":"Fix Messy PDF Copied Text — Clean Line Breaks","description":"Clean up ugly line breaks and formatting glitches when copying text from PDF files.","keywords":["fix pdf text","clean pdf copy","remove line breaks pdf"]}'::jsonb),
  ('pdf-merge-planner', 'PDF Merge & Combine Guide', 'PDF Tools', 'Organize files and inspect multiple PDF documents before merging or printing.', 'Combine', '/tools/pdf-merge-planner', 'file', true, false, false, 5, '{"title":"PDF File Inspector & Merge Prep","description":"Inspect and prepare multiple PDF files for document assembly.","keywords":["pdf merge","combine pdf","pdf files"]}'::jsonb),
  ('pdf-page-number-gen', 'PDF Page Numbering Labeler', 'PDF Tools', 'Generate customizable page number headers and footers for PDF documents.', 'FileDigit', '/tools/pdf-page-number-gen', 'form', true, false, false, 6, '{"title":"PDF Page Number Format Generator","description":"Create custom header/footer numbering labels for reports and ebooks.","keywords":["pdf page numbers","pdf numbering","footer labels"]}'::jsonb),
  ('pdf-size-estimator', 'PDF Compression & Size Estimator', 'PDF Tools', 'Calculate potential file size savings and target compression ratios before emailing PDFs.', 'Minimize2', '/tools/pdf-size-estimator', 'file', true, false, false, 7, '{"title":"PDF Size & Compression Estimator","description":"Estimate compressed PDF size and optimization metrics.","keywords":["compress pdf size","pdf optimizer","reduce pdf size"]}'::jsonb),
  ('pdf-unlock-checker', 'PDF Security & Encryption Inspector', 'PDF Tools', 'Check if a PDF file is password protected, encrypted, or has printing/copy restrictions.', 'Lock', '/tools/pdf-unlock-checker', 'file', true, false, false, 8, '{"title":"PDF Security & Password Status Checker","description":"Inspect PDF document permissions and security locks.","keywords":["check pdf password","pdf security status","pdf restrictions"]}'::jsonb),
  ('pdf-watermark-generator', 'PDF Watermark Text Stamp Creator', 'PDF Tools', 'Create draft, confidential, or custom watermark text rules for overlaying on documents.', 'Stamp', '/tools/pdf-watermark-generator', 'form', true, false, false, 9, '{"title":"PDF Watermark Generator Online","description":"Generate custom text watermark stamp rules for confidential PDF files.","keywords":["pdf watermark","watermark stamp","confidential watermark"]}'::jsonb),
  ('pdf-to-base64', 'PDF to Base64 Encoder', 'PDF Tools', 'Convert PDF files into Base64 data URI strings for embedding in code or APIs.', 'Code', '/tools/pdf-to-base64', 'file', true, false, false, 10, '{"title":"PDF to Base64 Data URI Converter","description":"Convert PDF documents into Base64 encoded data strings.","keywords":["pdf to base64","encode pdf","base64 pdf URI"]}'::jsonb),
  ('base64-to-pdf', 'Base64 to PDF Decoder', 'PDF Tools', 'Paste Base64 data strings to convert back into downloadable PDF documents.', 'FileCheck', '/tools/base64-to-pdf', 'textarea', true, false, false, 11, '{"title":"Base64 to PDF File Decoder","description":"Decode Base64 text string into downloadable PDF document.","keywords":["base64 to pdf","decode base64 pdf","convert base64"]}'::jsonb),
  ('image-compressor', 'Image Compressor (PNG / JPG / WebP)', 'Image Tools', 'Compress PNG, JPG, and WebP images directly in your browser with adjustable quality levels.', 'Image', '/tools/image-compressor', 'image', true, true, true, 12, '{"title":"Free Online Image Compressor — PNG & JPG","description":"Reduce image file size in your browser without quality loss.","keywords":["image compressor","compress png","compress jpg","reduce image size"]}'::jsonb),
  ('image-resizer', 'Pixel Image Resizer', 'Image Tools', 'Resize image width and height dimensions with aspect ratio lock.', 'Maximize2', '/tools/image-resizer', 'image', true, false, true, 13, '{"title":"Online Image Resizer — Custom Pixel Width & Height","description":"Resize photos and graphics to exact pixel dimensions instantly.","keywords":["image resizer","resize photo","change image dimensions"]}'::jsonb),
  ('image-converter-webp', 'JPG/PNG to WebP Converter', 'Image Tools', 'Convert heavy PNG or JPEG photos into fast-loading WebP format.', 'RefreshCw', '/tools/image-converter-webp', 'image', true, true, false, 14, '{"title":"Convert PNG/JPG to WebP Image Format","description":"Convert images to high-compression WebP format for faster web speed.","keywords":["convert to webp","png to webp","jpg to webp"]}'::jsonb),
  ('jpg-to-png', 'JPG to PNG Converter', 'Image Tools', 'Convert JPEG images into high-quality PNG format with lossless encoding.', 'FileImage', '/tools/jpg-to-png', 'image', true, false, false, 15, '{"title":"JPG to PNG Converter Online","description":"Convert JPG images to PNG format instantly.","keywords":["jpg to png","convert jpeg to png","image converter"]}'::jsonb),
  ('png-to-jpg', 'PNG to JPG Converter (Solid White Background)', 'Image Tools', 'Convert transparent or large PNG images to lightweight JPG graphics.', 'FileImage', '/tools/png-to-jpg', 'image', true, false, false, 16, '{"title":"PNG to JPG Converter Online","description":"Convert PNG graphics to JPG format with solid background fill.","keywords":["png to jpg","convert png to jpeg","photo converter"]}'::jsonb),
  ('color-picker-image', 'Image Color Palette Extractor', 'Image Tools', 'Upload an image to automatically extract dominant HEX, RGB, and color scheme codes.', 'Palette', '/tools/color-picker-image', 'image', true, false, false, 17, '{"title":"Image Color Palette & HEX Code Extractor","description":"Extract dominant color scheme and HEX codes from any uploaded photo.","keywords":["image color picker","color palette generator","extract hex from image"]}'::jsonb),
  ('image-to-base64', 'Image to Base64 String Encoder', 'Image Tools', 'Convert PNG, JPG, or SVG images into inline CSS/HTML Base64 Data URLs.', 'Code', '/tools/image-to-base64', 'image', true, false, false, 18, '{"title":"Image to Base64 Converter Online","description":"Convert images into Base64 data strings for inline CSS/HTML.","keywords":["image to base64","base64 image encoder","data uri image"]}'::jsonb),
  ('base64-to-image', 'Base64 to Image Decoder', 'Image Tools', 'Paste Base64 Data URLs to render and download as PNG/JPG graphics.', 'Download', '/tools/base64-to-image', 'textarea', true, false, false, 19, '{"title":"Base64 to Image Decoder & Previewer","description":"Decode Base64 strings back into viewable PNG or JPG images.","keywords":["base64 to image","decode base64 image","base64 image viewer"]}'::jsonb),
  ('favicon-generator', 'Favicon & App Icon Generator (16x16, 32x32, 64x64)', 'Image Tools', 'Convert logo graphics into square 16x16, 32x32, and 64x64 favicon PNG files.', 'Globe', '/tools/favicon-generator', 'image', true, true, false, 20, '{"title":"Favicon & Website Icon Generator","description":"Generate multi-resolution favicon graphics for web projects.","keywords":["favicon generator","make favicon","website icon creator"]}'::jsonb),
  ('image-blur-tool', 'Image Blur & Privacy Masking', 'Image Tools', 'Apply subtle gaussian blur filters to protect sensitive information or create backgrounds.', 'EyeOff', '/tools/image-blur-tool', 'image', true, false, false, 21, '{"title":"Image Blur & Background Masking Tool","description":"Apply privacy blur effects to photos and background graphics.","keywords":["blur image","photo blur tool","privacy mask photo"]}'::jsonb),
  ('image-grayscale', 'Grayscale & Black/White Photo Filter', 'Image Tools', 'Convert full-color photos into dramatic high-contrast monochrome black & white graphics.', 'Moon', '/tools/image-grayscale', 'image', true, false, false, 22, '{"title":"Black & White Photo Converter Online","description":"Convert color photos to monochrome black and white graphics.","keywords":["grayscale image","black and white converter","monochrome photo"]}'::jsonb),
  ('image-cropper', 'Square 1:1 Image Cropper & Avatar Maker', 'Image Tools', 'Crop images into clean 1:1 square aspect ratios for social media avatars and logos.', 'Crop', '/tools/image-cropper', 'image', true, false, false, 23, '{"title":"Square Image Cropper & Profile Avatar Maker","description":"Crop graphics into perfect 1:1 square dimensions for avatars.","keywords":["square crop","profile photo cropper","avatar creator"]}'::jsonb),
  ('svg-data-uri-gen', 'SVG Code to Data URI Converter', 'Image Tools', 'Encode inline raw SVG XML markup into clean URL-encoded CSS background-image URIs.', 'Code', '/tools/svg-data-uri-gen', 'textarea', true, false, false, 24, '{"title":"SVG to CSS Data URI Encoder","description":"Convert raw SVG code into CSS background-image data URI strings.","keywords":["svg to data uri","encode svg","svg css background"]}'::jsonb),
  ('image-flipper-rotator', 'Image Rotate & Flip Tool', 'Image Tools', 'Rotate photos 90°, 180°, or 270° and mirror flip horizontally or vertically.', 'RotateCw', '/tools/image-flipper-rotator', 'image', true, false, false, 25, '{"title":"Rotate & Flip Image Online Tool","description":"Rotate images 90 degrees or flip horizontally and vertically.","keywords":["rotate image","flip photo","mirror image online"]}'::jsonb),
  ('social-image-dimensions', 'Social Media Image Dimension Cheat Sheet', 'Image Tools', 'Quick reference guide for Instagram, LinkedIn, YouTube, Facebook, and Twitter banner sizes.', 'Layout', '/tools/social-image-dimensions', 'none', true, false, false, 26, '{"title":"Social Media Image Dimensions Guide 2026","description":"Check exact image size requirements for Instagram, LinkedIn, YouTube, and Facebook.","keywords":["social media sizes","instagram photo dimensions","linkedin banner size"]}'::jsonb),
  ('word-counter', 'Word Counter', 'Text & Content Tools', 'Live counting of words, characters, sentences, paragraphs, and estimated reading time.', 'FileText', '/tools/word-counter', 'textarea', true, true, true, 27, '{"title":"Free Word Counter — BRANIFY Tools","description":"Count words, characters, sentences, paragraphs, and reading time instantly.","keywords":["word counter","count words","word count tool"]}'::jsonb),
  ('character-counter', 'Character Counter', 'Text & Content Tools', 'Count exact characters with and without spaces, plus letter and symbol breakdowns.', 'Hash', '/tools/character-counter', 'textarea', true, false, true, 28, '{"title":"Character Counter Online","description":"Count total characters with and without spaces for posts and ads.","keywords":["character counter","count characters","letter counter"]}'::jsonb),
  ('sentence-counter', 'Sentence Counter', 'Text & Content Tools', 'Count total sentences and average sentence length in words.', 'ListFilter', '/tools/sentence-counter', 'textarea', true, false, false, 29, '{"title":"Sentence Counter Tool","description":"Analyze total sentences and readability metrics.","keywords":["sentence counter","count sentences"]}'::jsonb),
  ('paragraph-counter', 'Paragraph Counter', 'Text & Content Tools', 'Count total paragraphs and content block structure.', 'AlignLeft', '/tools/paragraph-counter', 'textarea', true, false, false, 30, '{"title":"Paragraph Counter Tool","description":"Count paragraphs and block sections in copy.","keywords":["paragraph counter","count paragraphs"]}'::jsonb),
  ('reading-time-calculator', 'Reading Time Calculator', 'Text & Content Tools', 'Calculate estimated silent reading time and speech presentation duration.', 'Clock', '/tools/reading-time-calculator', 'textarea', true, false, false, 31, '{"title":"Reading & Speaking Time Calculator","description":"Calculate estimated reading time and speech duration.","keywords":["reading time calculator","speech length calculator"]}'::jsonb),
  ('case-converter', 'Case Converter', 'Text & Content Tools', 'Convert text between UPPERCASE, lowercase, Title Case, camelCase, kebab-case, and snake_case.', 'Type', '/tools/case-converter', 'textarea', true, false, true, 32, '{"title":"Online Case Converter Tool","description":"Transform copy into UPPERCASE, lowercase, Title Case, camelCase, kebab-case.","keywords":["case converter","uppercase","lowercase","title case"]}'::jsonb),
  ('uppercase-converter', 'Uppercase Converter', 'Text & Content Tools', 'Convert all text letters into bold ALL CAPS UPPERCASE.', 'Type', '/tools/uppercase-converter', 'textarea', true, false, false, 33, '{"title":"Uppercase Converter Tool","description":"Convert copy into ALL CAPS UPPERCASE.","keywords":["uppercase converter","all caps"]}'::jsonb),
  ('lowercase-converter', 'Lowercase Converter', 'Text & Content Tools', 'Convert all text letters into clean lowercase characters.', 'Type', '/tools/lowercase-converter', 'textarea', true, false, false, 34, '{"title":"Lowercase Converter Tool","description":"Convert copy into lowercase text.","keywords":["lowercase converter","small letters"]}'::jsonb),
  ('title-case-converter', 'Title Case Converter', 'Text & Content Tools', 'Capitalize the first letter of each word for headlines and titles.', 'Type', '/tools/title-case-converter', 'textarea', true, false, false, 35, '{"title":"Title Case Converter Tool","description":"Capitalize title words for articles and headlines.","keywords":["title case converter","capitalize title"]}'::jsonb),
  ('duplicate-line-remover', 'Remove Duplicate Lines', 'Text & Content Tools', 'Filter out duplicate lines from list data while preserving original sequence.', 'ListOrdered', '/tools/duplicate-line-remover', 'textarea', true, false, false, 36, '{"title":"Remove Duplicate Lines Online Tool","description":"Remove duplicate lines from lists and data.","keywords":["remove duplicate lines","deduplicate list"]}'::jsonb),
  ('remove-extra-spaces', 'Remove Extra Spaces', 'Text & Content Tools', 'Clean text by stripping multiple spaces, double line breaks, and trailing tabs.', 'Sparkles', '/tools/remove-extra-spaces', 'textarea', true, false, false, 37, '{"title":"Remove Double Spaces & Blank Lines","description":"Clean text copy by removing extra spaces.","keywords":["remove extra spaces","clean text"]}'::jsonb),
  ('text-sorter', 'Text Sorter', 'Text & Content Tools', 'Sort lists alphabetically (A-Z or Z-A) or by line length.', 'ArrowUpDown', '/tools/text-sorter', 'textarea', true, false, false, 38, '{"title":"Alphabetical Text & List Sorter","description":"Sort lines alphabetically or by length.","keywords":["text sorter","alphabetical sorter"]}'::jsonb),
  ('text-reverser', 'Text Reverser', 'Text & Content Tools', 'Reverse text characters, word order, or line sequences.', 'RotateCcw', '/tools/text-reverser', 'textarea', true, false, false, 39, '{"title":"Text Reverser Tool","description":"Reverse characters or word orders.","keywords":["text reverser","flip text"]}'::jsonb),
  ('text-cleaner', 'Text Cleaner', 'Text & Content Tools', 'Sanitize text, strip HTML tags, fix broken line breaks, and clean unprintable characters.', 'Sparkles', '/tools/text-cleaner', 'textarea', true, false, false, 40, '{"title":"Text Cleaner & Sanitizer Tool","description":"Clean text formatting and strip invalid symbols.","keywords":["text cleaner","sanitize text"]}'::jsonb),
  ('find-and-replace', 'Find & Replace', 'Text & Content Tools', 'Search and replace words or phrases inside large copy blocks.', 'Search', '/tools/find-and-replace', 'form', true, false, false, 41, '{"title":"Find & Replace Text Tool","description":"Find and replace target words across long documents.","keywords":["find and replace","replace text"]}'::jsonb),
  ('lorem-ipsum-generator', 'Lorem Ipsum Generator', 'Text & Content Tools', 'Generate paragraphs or words of standard dummy placeholder text.', 'AlignLeft', '/tools/lorem-ipsum-generator', 'form', true, false, false, 42, '{"title":"Lorem Ipsum Filler Text Generator","description":"Generate custom lorem ipsum filler text for website design.","keywords":["lorem ipsum generator","filler text"]}'::jsonb),
  ('random-text-generator', 'Random Text Generator', 'Text & Content Tools', 'Generate randomized mock sentences, paragraphs, or word sequences.', 'Shuffle', '/tools/random-text-generator', 'form', true, false, false, 43, '{"title":"Random Text Generator Tool","description":"Generate random sentences for layout testing.","keywords":["random text generator","mock copy"]}'::jsonb),
  ('hashtag-generator', 'Hashtag Generator', 'Text & Content Tools', 'Generate targeted social media hashtags based on topic keywords.', 'Hash', '/tools/hashtag-generator', 'text', true, false, false, 44, '{"title":"Hashtag Generator Tool","description":"Generate popular hashtags for social posts.","keywords":["hashtag generator","social hashtags"]}'::jsonb),
  ('keyword-density-checker', 'Keyword Density Checker', 'Text & Content Tools', 'Analyze word frequencies and 1-word, 2-word, and 3-word phrase density percentages.', 'BarChart2', '/tools/keyword-density-checker', 'textarea', true, false, false, 45, '{"title":"Keyword Density Checker Tool","description":"Analyze keyword frequency and density percentages.","keywords":["keyword density checker","word frequency"]}'::jsonb),
  ('text-summarizer', 'Text Summarizer', 'Text & Content Tools', 'Extract key bullet sentences and core takeaways from long articles.', 'FileText', '/tools/text-summarizer', 'textarea', true, false, false, 46, '{"title":"Text Summarizer Tool","description":"Summarize long documents into concise key bullet points.","keywords":["text summarizer","summarize text"]}'::jsonb),
  ('json-formatter', 'JSON Formatter', 'Text & Content Tools', 'Beautify, validate, and format raw JSON code with syntax checks.', 'Code', '/tools/json-formatter', 'textarea', true, false, false, 47, '{"title":"JSON Formatter & Validator","description":"Format and beautify JSON objects with syntax validation.","keywords":["json formatter","beautify json"]}'::jsonb),
  ('markdown-formatter', 'Markdown Formatter', 'Text & Content Tools', 'Format Markdown text and generate live rendered HTML previews.', 'FileCode', '/tools/markdown-formatter', 'textarea', true, false, false, 48, '{"title":"Markdown Formatter & Previewer","description":"Format Markdown code and preview styled output.","keywords":["markdown formatter","markdown preview"]}'::jsonb),
  ('slug-generator', 'Slug Generator', 'Text & Content Tools', 'Convert headlines and titles into clean lowercased URL web slugs.', 'Link', '/tools/slug-generator', 'text', true, false, false, 49, '{"title":"URL Slug Generator Tool","description":"Generate clean URL web slugs from article titles.","keywords":["slug generator","url slug"]}'::jsonb),
  ('json-formatter-dev', 'JSON Formatter & Validator', 'Developer Tools', 'Pretty-print, validate, and structure raw JSON strings with 2-space indentation.', 'Code', '/tools/json-formatter-dev', 'textarea', true, true, true, 50, '{"title":"JSON Formatter & Validator Online","description":"Beautify and validate JSON objects with error highlighting.","keywords":["json formatter","json validator","beautify json"]}'::jsonb),
  ('json-minifier', 'JSON Minifier & Compact Tool', 'Developer Tools', 'Strip whitespaces and line breaks from JSON payloads to reduce bandwidth.', 'Minimize2', '/tools/json-minifier', 'textarea', true, false, false, 51, '{"title":"JSON Minifier & Compression Tool","description":"Minify JSON objects for faster API payloads.","keywords":["json minifier","compress json","single line json"]}'::jsonb),
