values
  ('aethel-luxury', 'Aethel Luxury Timepieces', 'E-Commerce Experience', 'Aethel Horology Group', 'An interactive 3D virtual showroom and bespoke checkout experience engineered for a Swiss independent luxury horology maison.', 'linear-gradient(135deg, #181920 0%, #2A261B 50%, #0F1014 100%)', ARRAY[]::text[], ARRAY['Web 3D Interactive Viewer','Custom Shopify Plus Store','Global Multi-Currency Engine','VIP Private Client Portal']::text[], '', '', 'Conversion Uplift: +54% · Avg Time on Site: 4m 18s · Annual Digital Volume: $18.4M', '', true, true, 0, '{"title":"Aethel Luxury Timepieces — Case Study | BRANIFY","description":"An interactive 3D virtual showroom and bespoke checkout experience engineered for a Swiss independent luxury horology maison."}'::jsonb),
  ('synapse-ai', 'Synapse Cognitive Cloud', 'AI Platform', 'Synapse Systems Inc.', 'Next-generation AI orchestration platform with real-time vector visualization, autonomous agent workflows, and sub-millisecond telemetry.', 'linear-gradient(135deg, #10121A 0%, #1D1E2C 50%, #090A0E 100%)', ARRAY[]::text[], ARRAY['Design System Architecture','Full-Stack Web App','Interactive Node Graph UI','Developer Documentation Engine']::text[], '', '', 'Active Enterprise Nodes: 140,000+ · Processing Latency: <24ms · Series B Capital: $45M', '', true, true, 1, '{"title":"Synapse Cognitive Cloud — Case Study | BRANIFY","description":"Next-generation AI orchestration platform with real-time vector visualization, autonomous agent workflows, and sub-millisecond telemetry."}'::jsonb),
  ('lumina-architects', 'Lumina Spatial Architecture', 'Luxury Brand Website', 'Lumina Studio Tokyo', 'A minimalist spatial digital experience documenting international architectural monuments through smooth web transitions and architectural typography.', 'linear-gradient(135deg, #141519 0%, #232220 50%, #0B0C0E 100%)', ARRAY[]::text[], ARRAY['Brand Identity Guidelines','Bespoke Custom Headless CMS','High-Res Image Optimization','Editorial Editorial Layouts']::text[], '', '', 'Global Design Awards: 6 Won · Page Speed Benchmark: 100 / 100 · Inquiry Lead Quality: +78%', '', true, true, 2, '{"title":"Lumina Spatial Architecture — Case Study | BRANIFY","description":"A minimalist spatial digital experience documenting international architectural monuments through smooth web transitions and architectural typography."}'::jsonb),
  ('nexus-exchange', 'Nexus Digital Marketplace', 'Digital Marketplace', 'Nexus Global Protocols', 'High-frequency asset marketplace engineered with instant orderbook execution, WebGL data depth charts, and institutional multi-sig security.', 'linear-gradient(135deg, #0C0F14 0%, #1A2129 50%, #08090C 100%)', ARRAY[]::text[], ARRAY['Real-Time WebSocket Engine','Dark-Mode Focused UI','Mobile Adaptive Web App','Institutional Security Audit']::text[], '', '', 'Monthly Trading Vol: $1.2B · Concurrent Users: 85,000+ · Crash Rate: 0.000%', '', false, true, 3, '{"title":"Nexus Digital Marketplace — Case Study | BRANIFY","description":"High-frequency asset marketplace engineered with instant orderbook execution, WebGL data depth charts, and institutional multi-sig security."}'::jsonb),
  ('quantis-analytics', 'Quantis Technology Dashboard', 'Technology Dashboard', 'Quantis Financial Tech', 'Precision risk management and financial modeling platform delivering real-time portfolio simulations for tier-one hedge funds.', 'linear-gradient(135deg, #121319 0%, #25221B 50%, #0A0B0E 100%)', ARRAY[]::text[], ARRAY['WebGL Data Visualizations','Dynamic Formula Builder','Role-Based Access Control','Multi-Monitor Display Mode']::text[], '', '', 'Data Points / Sec: 2.5M · Decision Speedup: 6.2x · Enterprise Retention: 99.4%', '', false, true, 4, '{"title":"Quantis Technology Dashboard — Case Study | BRANIFY","description":"Precision risk management and financial modeling platform delivering real-time portfolio simulations for tier-one hedge funds."}'::jsonb),
  ('verve-ventures', 'Verve Innovation Lab', 'Creative Business Website', 'Verve Ventures Global', 'An evocative portfolio portal connecting deep-tech startups with forward-thinking sovereign wealth funds and venture syndicates.', 'linear-gradient(135deg, #16171E 0%, #221D16 50%, #090A0D 100%)', ARRAY[]::text[], ARRAY['Custom WebGL Backgrounds','Pitch Deck Dynamic Hub','Interactive Portfolio Directory','Fast Automated Form Routing']::text[], '', '', 'Syndicate Deal Flow: $320M · Investor Engagement: +88% · Mobile Traffic Share: 62%', '', false, true, 5, '{"title":"Verve Innovation Lab — Case Study | BRANIFY","description":"An evocative portfolio portal connecting deep-tech startups with forward-thinking sovereign wealth funds and venture syndicates."}'::jsonb)
insert into public.products (slug, name, category, description, image, price, currency, status, delivery_info, file_url, featured, sort_order, seo)
values
  ('modern-saas-landing-page', 'Modern SaaS Landing Page Starter', 'Website Templates', 'A production-ready responsive landing page built with semantic HTML5, Tailwind CSS CDN, and high-contrast typography. Includes hero section with animated CTA, feature grids, pricing table toggle, testimonial cards, and an accessible FAQ accordion. Free to download and customize for personal and commercial projects.', '', 0, 'USD', 'active', 'License: MIT License — 100% Free for Commercial & Personal Use', '/downloads/templates/modern-saas-landing-starter.html', true, 1, '{"title":"Modern SaaS Landing Page Starter Template — 100% Free Download | BRANIFY","description":"Download this free, high-converting HTML5 & Tailwind CSS SaaS landing page template. Clean code, fully responsive, MIT licensed."}'::jsonb),
  ('creative-developer-portfolio', 'Creative Developer & Designer Portfolio', 'Website Templates', 'Showcase your software engineering work, technical competencies, and client case studies with this dark-mode HTML5 & Tailwind portfolio template. Features interactive project repository cards, skills chips, career experience timeline, and a functional contact brief form structure.', '', 0, 'USD', 'active', 'License: MIT License — 100% Free for Commercial & Personal Use', '/downloads/templates/developer-portfolio-starter.html', false, 2, '{"title":"Developer Portfolio HTML5 Starter Template — Free Download | BRANIFY","description":"Download a clean, modern developer & software engineer portfolio template in HTML5 and Tailwind CSS. 100% Free."}'::jsonb),
  ('client-master-services-agreement', 'Client Master Services Agreement (MSA) & SOW', 'Business Templates', 'A comprehensive, structured Master Services Agreement (MSA) and Statement of Work (SOW) template for digital agencies, freelance developers, and consultants. Covers scope of work, milestone payments (50/25/25), revision caps, intellectual property assignment upon final payment, confidentiality non-disclosure, and liability protections.', '', 0, 'USD', 'active', 'License: Free to use and adapt for personal and commercial business purposes', '/downloads/templates/client-master-services-agreement.txt', true, 3, '{"title":"Client Master Services Agreement & SOW Template — Free Download | BRANIFY","description":"Free Master Services Agreement (MSA) and Statement of Work template for digital agencies and freelancers."}'::jsonb),
  ('client-discovery-project-brief', 'Client Discovery Questionnaire & Project Brief', 'Business Templates', 'Save hours in client meetings and eliminate scope creep before kick-off. This 20-question discovery template helps agencies and freelancers extract business objectives, target audience demographics, technical requirements, competitor benchmarks, and launch timeline expectations.', '', 0, 'USD', 'active', 'License: Free for agency, freelance, and client onboarding use', '/downloads/templates/client-discovery-project-brief.txt', false, 4, '{"title":"Client Discovery Questionnaire & Project Brief Template — Free | BRANIFY","description":"Extract client goals, scope, and technical requirements with this 20-question discovery questionnaire template."}'::jsonb),
  ('ats-optimized-tech-resume', 'ATS-Optimized Tech Resume Template', 'Resume / CV Templates', 'Engineered specifically to pass Applicant Tracking Systems (ATS) algorithms. Uses clean single-column structure, standard section headers, keyword optimization placeholders, and impact-driven action verb bullet formulas ([Action] + [Context] + [Measurable Outcome %]).', '', 0, 'USD', 'active', 'License: Free to use and modify for personal career development', '/downloads/templates/ats-optimized-tech-resume.txt', true, 5, '{"title":"ATS-Optimized Tech Resume Template — Free Download | BRANIFY","description":"Download this free single-column ATS-friendly resume template for software engineers, designers, and tech professionals."}'::jsonb),
  ('seed-startup-pitch-deck', 'Seed Startup Pitch Deck Structure & Blueprint', 'Presentation Templates', 'The battle-tested 15-slide pitch deck structure utilized by venture-backed startups to raise Pre-Seed and Seed capital. For every slide, this guide details the exact Purpose, What to Include, Key Metrics to Highlight, and Common Mistakes to avoid before pitching angel investors and VC partners.', '', 0, 'USD', 'active', 'License: Free for startup fundraising and pitch deck creation', '/downloads/templates/seed-startup-pitch-deck-structure.txt', true, 6, '{"title":"Seed Startup Pitch Deck Structure & Blueprint — Free Download | BRANIFY","description":"15-slide pitch deck framework for founders raising Seed & Pre-Seed capital. Free download from BRANIFY."}'::jsonb),
  ('startup-runway-cashflow-model', 'Startup Runway & Cash Flow Financial Model', 'Spreadsheet Templates', 'A 12-month cash flow and runway projection spreadsheet model formatted in standard CSV. Seamlessly importable into Excel, Google Sheets, Apple Numbers, or Notion. Includes monthly beginning cash, recurring MRR, services revenue, granular operating expenses (payroll, marketing, software, cloud), net burn rate, and calculated runway months.', '', 0, 'USD', 'active', 'License: Free to use and adapt for personal and commercial financial modeling', '/downloads/templates/startup-runway-cashflow-model.csv', true, 7, '{"title":"Startup Runway & Cash Flow Financial Model (CSV/Excel) — Free | BRANIFY","description":"Calculate startup burn rate, cash flow, and runway with this 12-month financial model spreadsheet. Free CSV download."}'::jsonb),
  ('social-media-content-calendar', 'Multi-Platform Social Media Content Calendar', 'Social Media Templates', 'Organize your brand publishing strategy across LinkedIn, Twitter/X, Instagram, TikTok, and Newsletters. This multi-channel editorial matrix spreadsheet includes fields for publishing dates, target pillars, hooks/headlines, caption copy, call-to-action triggers, visual asset statuses, and engagement goals.', '', 0, 'USD', 'active', 'License: Free for personal and commercial marketing management', '/downloads/templates/social-media-content-calendar.csv', false, 8, '{"title":"Multi-Platform Social Media Content Calendar (CSV) — Free Download | BRANIFY","description":"Plan, schedule, and organize social media posts across LinkedIn, Twitter, and Instagram with this free content calendar matrix."}'::jsonb),
  ('agency-brand-guidelines-canva', 'Agency Brand Guidelines Presentation Deck', 'Canva Templates', 'A 25-slide Canva presentation template crafted for branding agencies and identity designers to present brand guidelines to enterprise clients. Includes slides for brand mission, typography hierarchy, primary and secondary color palettes, logo exclusion zones, photography art direction, and digital asset usage rules.', '', 0, 'USD', 'coming_soon', 'License: Free to edit in Canva for personal & commercial client deliverables', '', false, 9, '{"title":"Agency Brand Guidelines Canva Template — Coming Soon | BRANIFY","description":"25-slide minimalist brand identity presentation kit in Canva. Coming soon to BRANIFY Free Templates."}'::jsonb),
  ('freelance-client-portal-notion', 'Freelance Client Portal & Project Hub', 'Notion Templates', 'A streamlined client portal dashboard built in Notion. Gives your clients a unified, transparent view of project milestones, asset deliverables, shared Google Drive folders, meeting notes, invoice statuses, and feedback revision logs.', '', 0, 'USD', 'coming_soon', 'License: Free to duplicate and share with unlimited clients', '', false, 10, '{"title":"Freelance Client Portal Notion Template — Coming Soon | BRANIFY","description":"All-in-one client dashboard in Notion for asynchronous project delivery and feedback. Coming soon to BRANIFY."}'::jsonb)
